const SPECIES_COUNT = 4;
const COLORS = [
  [255, 80, 80],
  [80, 255, 80],
  [80, 120, 255],
  [255, 220, 80]
];
const NAMES = ["RED", "GREEN", "BLUE", "YELLOW"];

let particles = [];
let interactions = [];
let currentSpecies = 0;
let friction = 0.85;
let interactionRadius = 120;
let trailAlpha = 30;
let showTrails = true;
let attractionMatrix;
let particleCount = 0;
let foodSources = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(RGB);

  // Generate random but balanced interaction matrix
  generateNewRules();

  // Initial population
  for (let s = 0; s < SPECIES_COUNT; s++) {
    for (let i = 0; i < 80; i++) {
      spawnParticle(random(width), random(height), s);
    }
  }

  // Create food sources
  for (let i = 0; i < 3; i++) {
    foodSources.push({
      x: random(100, width - 100),
      y: random(100, height - 100),
      radius: 60,
      pulse: random(TWO_PI)
    });
  }
}

function generateNewRules() {
  attractionMatrix = [];
  for (let i = 0; i < SPECIES_COUNT; i++) {
    attractionMatrix[i] = [];
    for (let j = 0; j < SPECIES_COUNT; j++) {
      // Random attraction between -0.8 and 0.8
      attractionMatrix[i][j] = random(-0.8, 0.8);
    }
  }
}

function spawnParticle(x, y, species) {
  particles.push({
    x: x,
    y: y,
    vx: random(-1, 1),
    vy: random(-1, 1),
    species: species,
    age: 0,
    size: random(3, 6)
  });
  particleCount++;
}

function draw() {
  // Trail effect
  if (showTrails) {
    fill(10, 10, 20, trailAlpha);
    noStroke();
    rect(0, 0, width, height);
  } else {
    background(10, 10, 20);
  }

  // Draw food sources
  for (let food of foodSources) {
    food.pulse += 0.03;
    let pulseSize = sin(food.pulse) * 10;

    noFill();
    strokeWeight(2);
    for (let r = 20; r < food.radius + pulseSize; r += 15) {
      let alpha = map(r, 20, food.radius + pulseSize, 200, 0);
      stroke(255, 255, 255, alpha);
      ellipse(food.x, food.y, r * 2);
    }

    fill(255, 255, 255, 150);
    noStroke();
    ellipse(food.x, food.y, 8);
  }

  // Update and draw particles
  for (let p of particles) {
    p.age++;

    // Apply forces from all other particles
    let fx = 0, fy = 0;
    let nearbyCount = 0;

    for (let other of particles) {
      if (p === other) continue;

      let dx = other.x - p.x;
      let dy = other.y - p.y;
      let dist = sqrt(dx*dx + dy*dy);

      if (dist > 0 && dist < interactionRadius) {
        let force = attractionMatrix[p.species][other.species];
        // Softening: avoid infinite forces at close range
        let strength = force * (1 - dist / interactionRadius);
        // Repel very close particles (collision avoidance)
        if (dist < 15) {
          strength -= 0.5 * (1 - dist / 15);
        }

        fx += (dx / dist) * strength * 0.5;
        fy += (dy / dist) * strength * 0.5;
        nearbyCount++;
      }
    }

    // Attraction to food sources
    for (let food of foodSources) {
      let dx = food.x - p.x;
      let dy = food.y - p.y;
      let d = sqrt(dx*dx + dy*dy);
      if (d > 0 && d < 200) {
        let f = 0.02 * (1 - d/200);
        fx += (dx/d) * f;
        fy += (dy/d) * f;
      }
    }

    // Mouse interaction - create a force field
    if (mouseIsPressed) {
      let mx = mouseX;
      let my = mouseY;
      let dx = mx - p.x;
      let dy = my - p.y;
      let d = sqrt(dx*dx + dy*dy);
      if (d > 0 && d < 250) {
        // Repulsive force from mouse
        let mForce = -0.8 * (1 - d/250);
        fx += (dx/d) * mForce;
        fy += (dy/d) * mForce;
      }
    }

    // Update velocity
    p.vx += fx;
    p.vy += fy;
    p.vx *= friction;
    p.vy *= friction;

    // Update position
    p.x += p.vx;
    p.y += p.vy;

    // Bounce off walls
    if (p.x < 0) { p.x = 0; p.vx *= -1; }
    if (p.x > width) { p.x = width; p.vx *= -1; }
    if (p.y < 0) { p.y = 0; p.vy *= -1; }
    if (p.y > height) { p.y = height; p.vy *= -1; }

    // Draw particle with glow
    let col = COLORS[p.species];

    // Glow
    noStroke();
    for (let g = 3; g > 0; g--) {
      let alpha = 40 / g;
      fill(col[0], col[1], col[2], alpha);
      ellipse(p.x, p.y, p.size * (g + 2));
    }

    // Core
    fill(col[0], col[1], col[2], 220);
    ellipse(p.x, p.y, p.size);
  }

  // Draw UI overlay
  drawUI();
}

function drawUI() {
  // Background panel
  fill(0, 0, 0, 180);
  noStroke();
  rect(10, 10, 340, 280, 10);

  // Title
  fill(255);
  textSize(18);
  textFont('monospace');
  text("PARTICLE LIFE SIMULATION", 25, 35);

  textSize(12);
  fill(200);
  text("Emergent artificial ecosystem", 25, 52);

  // Species info
  let y = 75;
  for (let s = 0; s < SPECIES_COUNT; s++) {
    let col = COLORS[s];
    let isSelected = (s === currentSpecies);

    fill(col[0], col[1], col[2]);
    ellipse(35, y + 5, isSelected ? 14 : 10);

    fill(isSelected ? 255 : 180);
    text(`${NAMES[s]}${isSelected ? " [SELECTED]" : ""}`, 50, y + 8);
    y += 22;
  }

  // Interaction matrix mini-view
  textSize(10);
  fill(150);
  text("INTERACTION MATRIX:", 25, y + 5);
  y += 18;

  let cellSize = 28;
  for (let i = 0; i < SPECIES_COUNT; i++) {
    for (let j = 0; j < SPECIES_COUNT; j++) {
      let val = attractionMatrix[i][j];
      let c = val > 0 ? [0, map(val, 0, 0.8, 100, 255), 0] : [map(abs(val), 0, 0.8, 100, 255), 0, 0];
      fill(c[0], c[1], c[2], 180);
      noStroke();
      rect(25 + j * cellSize, y + i * cellSize * 0.7, cellSize - 2, cellSize * 0.6, 3);
    }
  }
  y += SPECIES_COUNT * cellSize * 0.7 + 15;

  // Stats
  fill(180);
  text(`Particles: ${particles.length}`, 25, y);
  text(`FPS: ${Math.round(frameRate())}`, 140, y);

  // Instructions
  y += 25;
  fill(255, 255, 200);
  text("CLICK: Spawn particles | 1-4: Change species", 25, y);
  y += 14;
  text("R: New rules | C: Clear | T: Toggle trails | SPACE: Pause", 25, y);
}

function mousePressed() {
  // Don't spawn if clicking on UI
  if (mouseX < 360 && mouseY < 290) return;

  // Spawn burst of particles
  for (let i = 0; i < 5; i++) {
    spawnParticle(
      mouseX + random(-20, 20),
      mouseY + random(-20, 20),
      currentSpecies
    );
  }
}

function mouseDragged() {
  if (mouseX < 360 && mouseY < 290) return;

  if (frameCount % 3 === 0) {
    spawnParticle(
      mouseX + random(-10, 10),
      mouseY + random(-10, 10),
      currentSpecies
    );
  }
}

function keyPressed() {
  if (key === '1') currentSpecies = 0;
  if (key === '2') currentSpecies = 1;
  if (key === '3') currentSpecies = 2;
  if (key === '4') currentSpecies = 3;

  if (key === 'r' || key === 'R') {
    generateNewRules();
    // Add flash effect
    background(255);
  }

  if (key === 'c' || key === 'C') {
    particles = [];
    particleCount = 0;
  }

  if (key === 't' || key === 'T') {
    showTrails = !showTrails;
  }

  if (key === ' ') {
    isLooping() ? noLoop() : loop();
  }

  // Randomize food source positions
  if (key === 'f' || key === 'F') {
    for (let food of foodSources) {
      food.x = random(100, width - 100);
      food.y = random(100, height - 100);
    }
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

